contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address spender, uint256 approved, uint256 subtracted) public {
        require(spender != address(0));
        bool ok1; try c.approve(spender, approved) { ok1 = true; } catch { ok1 = false; }
        uint256 afterApprove = c.allowance(address(this), spender);
        bool reverted;
        if (subtracted > afterApprove) {
            try c.decreaseAllowance(spender, subtracted) { reverted = false; } catch { reverted = true; }
        } else {
            reverted = false;
            c.decreaseAllowance(spender, subtracted);
        }
        uint256 finalAllowance = c.allowance(address(this), spender);
        if (reverted) {
            assert(finalAllowance == approved);
        } else {
            assert(finalAllowance + subtracted == approved);
        }
    }
    receive() external payable {}
}

