contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 amountUp, uint256 amountDown) public {
        require(spender != address(0));
        require(amountDown > amountUp);

        // Establish an allowance of amountUp for spender.
        c.increaseAllowance(spender, amountUp);
        uint256 before = c.allowance(address(this), spender);

        // Decreasing by more than the current allowance must revert and not change state.
        bool reverted;
        try c.decreaseAllowance(spender, amountDown) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted == true &&
            before == amountUp &&
            c.allowance(address(this), spender) == before
        );
    }

    receive() external payable {}
}

