contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address minter, uint256 mintAmount, uint256 burnAmount) public {
        require(minter != address(0));
        require(mintAmount > 0);

        // Cannot mint directly; use transferFrom-style setup is unavailable, so use burn on zero balance for revert case first is not possible.
        // Instead: minting is only callable by curated pools, so this contract's balance is always 0.
        // Rule tested: any burn attempt by an account with zero balance must revert,
        // leaving the account's balance at 0 and totalSupply unchanged.
        uint256 supplyBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));

        bool reverted;
        try c.burn(burnAmount) { reverted = false; } catch { reverted = true; }

        uint256 supplyAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));

        assert(
            reverted &&
            balBefore == 0 &&
            balAfter == 0 &&
            supplyAfter == supplyBefore
        );
    }

    receive() external payable {}
}

