contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public {
        // setup: get tokens to burn by minting via transfer path unavailable; use balances directly
        // We need tokens: deployer of c is this contract, but no public mint. Instead use transfer invariants.
        // Fallback rule: after transfer of amount from self (needs balance). Use burn rule only if balance suffices.
        bool ok = true;
        uint balBefore = c.balanceOf(address(this));
        uint supplyBefore = c.totalSupply();
        if (amount <= balBefore) {
            c.burn(amount);
            ok = true;
        } else {
            ok = false;
        }
        uint balAfter = c.balanceOf(address(this));
        uint supplyAfter = c.totalSupply();
        assert(!ok ? balAfter == balBefore : (balAfter == balBefore - amount && supplyAfter == supplyBefore - amount));
    }
    receive() external payable {}
}

