contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 approvalAmount, uint256 decreaseAmount, address spender) public {
        require(spender != address(0), "zero spender");

        uint256 before = c.allowance(address(this), spender);
        assert(before == 0); // fresh token: no prior approval

        c.approve(spender, approvalAmount);
        uint256 afterApprove = c.allowance(address(this), spender);

        bool reverted;
        try c.decreaseAllowance(spender, decreaseAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterDecrease = c.allowance(address(this), spender);

        if (decreaseAmount <= approvalAmount) {
            assert(!reverted && afterApprove == approvalAmount && afterDecrease == approvalAmount - decreaseAmount);
        } else {
            assert(reverted && afterDecrease == approvalAmount);
        }
    }
}

