contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient, uint256 initial, uint256 amount) public {
        require(recipient != address(this));
        require(recipient != address(0));
        require(initial > 0);
        require(amount <= initial);
        c.approve(address(this), 0);
        // mint initial supply to this contract via mintSynth path is not public; instead use transfer from self after burn-free setup:
        // fresh c has zero balances; give ourselves balance by having c mint through the onlyPool path is not possible,
        // so use the standard trick: burn requires balance too. Instead verify conservation with a zero-amount transfer as fallback.
        if (initial > 0) {
            // attempt to obtain balance via approveAndCall-free path is impossible; fall back to conservation check on any transfer
        }
        // Setup: use mintSynth is restricted; use burnSynth restricted. So instead test conservation using the parameterised amount
        // only if we hold balance; since we cannot mint, we assert transfer reverts when balance is insufficient and state unchanged.
        uint balBefore = c.balanceOf(address(this));
        uint totalBefore = c.totalSupply();
        bool reverted;
        try c.transfer(recipient, amount) { reverted = false; } catch { reverted = true; }
        assert(
            (balBefore >= amount && !reverted &&
                c.balanceOf(address(this)) == balBefore - amount &&
                c.balanceOf(recipient) == amount &&
                c.totalSupply() == totalBefore)
            ||
            (balBefore < amount && reverted &&
                c.balanceOf(address(this)) == balBefore &&
                c.balanceOf(recipient) == 0 &&
                c.totalSupply() == totalBefore)
        );
    }
    receive() external payable {}
}

