        uint256 afterVal = c.allowance(address(this), spender);
        assert(before == a1 && afterVal == a1 - sub);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 amount, uint256 extra) public {
        require(spender != address(0));
        require(extra != 0);

        c.approve(spender, amount);
        uint256 a1 = c.allowance(address(this), spender);
        assert(a1 == amount);

        c.increaseAllowance(spender, extra);
        uint256 a2 = c.allowance(address(this), spender);
        assert(a2 == amount + extra);

        bool reverted;
        try c.decreaseAllowance(spender, amount + extra + 1) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 a3 = c.allowance(address(this), spender);
        assert(reverted && a3 == a2);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint256 allowAmt) public {
        require(recipient != address(0));

        c.approve(address(this), allowAmt);

        uint256 senderBalBefore = c.balanceOf(address(this));
        uint256 recipBalBefore = c.balanceOf(recipient);
        uint256 supplyBefore = c.totalSupply();
        uint256 allowBefore = c.allowance(address(this), address(this));

        bool ok = c.transferFrom(address(this), recipient, 0);

        uint256 senderBalAfter = c.balanceOf(address(this));
        uint256 recipBalAfter = c.balanceOf(recipient);
        uint256 supplyAfter = c.totalSupply();
        uint256 allowAfter = c.allowance(address(this), address(this));

        assert(
            ok &&
            senderBalAfter == senderBalBefore &&
            recipBalAfter == recipBalBefore &&
            supplyAfter == supplyBefore &&
            allowAfter == allowBefore &&
            allowBefore == allowAmt
        );
    }

    receive() external payable {}
}
